import{z as o,x as p,o as e,c as B,q as i,j as n,D as E,d as l,s as r,S as s,b as A}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"能力对 ACL","description":"","frontmatter":{"title":"能力对 ACL","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/capability-vs-acl.md","filePath":"cs/capability-vs-acl.md","lastUpdated":1791063341000}'),C={name:"cs/capability-vs-acl.md"};function d(m,a,D,c,L,u){const t=p("Mermaid");return e(),B("div",null,[a[2]||(a[2]=i('<h1 id="能力对-acl" tabindex="-1">能力对 ACL <a class="header-anchor" href="#能力对-acl" aria-label="Permalink to &quot;能力对 ACL&quot;">​</a></h1><div class="epigraph"><p>ACL 问「这个对象允许谁」；能力是主体持有的不可伪造票，「持票即允许」。混淆代理人在票与名字分离时更容易出现。</p><footer>—— 据 Lampson；Dennis and Van Horn, Programming Semantics for Multiprogrammed Computations, 1966</footer></div><p><a href="/cs/dac-mac-rbac">上一课</a>给出保护矩阵与最小特权。本课不重列 DAC/MAC。缺口是：矩阵有两种常用表示。按列存是 ACL（客体上的名单）；按行发不可伪造引用是能力。Unix fd、某些微内核的 cap 是能力直觉；文件 mode 与许多 Web ACL 是另一极。两者都能实现同一矩阵，失败模式不同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ACL 检查「名字 → 主体是否在名单」。若服务用自己的高权限去碰用户指定的名字，就变成混淆代理人：用户骗服务去打开它本不该碰的客体。能力把「打开」的结果变成持有的票，之后只认票，不认用户又递来的路径字符串。缺口不是新的 CIA 轴，而是表示如何改变委托与代理解引用。</p><p><span class="marginnote">Unix：路径查找走 ACL 式的目录权限；得到的 fd 更像能力。两种同时存在，所以「Linux 是 ACL 系统」这句话过粗。</span></p><p><span class="marginnote">直觉类比：能力像电影票——检票时只看票，手里有票就能进场，票还能转送给别人；ACL 像门口的会员名单——按名字查有没有你。票好送人，名单改一行就能拉黑，各有各的方便。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>能力：不可伪造、可传递（或显式收窄后传递）、与操作绑定。实现靠内核表或带 MAC 的令牌。ACL：改策略集中，列出「谁被撤销」容易；能力撤销要回收票或换纪元。本课不设计新操作系统，只对照：委托、撤销、命名。</p>',9)),(e(),n(s,null,{default:E(()=>[r(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAT%5B%22%E4%BF%9D%E6%8A%A4%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20ACL%5B%22%E6%8C%89%E5%AE%A2%E4%BD%93%3A%20ACL%22%5D%0A%20%20MAT%20--%3E%20CAP%5B%22%E6%8C%89%E4%B8%BB%E4%BD%93%3A%20%E8%83%BD%E5%8A%9B%22%5D%0A%20%20CAP%20--%3E%20BO%5B%22%E5%90%8E%E8%AF%BE%3A%20%E7%BC%93%E5%86%B2%E5%8C%BA%E6%BA%A2%E5%87%BA%E7%9B%B4%E8%A7%89%22%5D%0A%20%20ACL%20--%3E%20BO%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[l("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,"最小特权在能力系统里常表现为「只把需要的票传入进程」。ACL 系统靠每次查找重新求值名单，适合集中改策略。分布式下能力像带签名的票（下一课证书已会签）；ACL 则要在每次访问问权威。混淆代理人的修复可以是：不接受名字、只接受已持有的能力，或绑定「用哪一张票去访问」。",-1)),a[5]||(a[5]=A("p",null,[A("span",{class:"marginnote"},"术语翻译：混淆代理人就是「高权限的中间人被低权限用户借刀」——服务替你取 URL、编译器替你写报告，用的都是它自己的权限而不是你的；你只需递给它一个它有权限、而你没有的名字。")],-1)),a[6]||(a[6]=A("p",null,"撤销能力常用纪元或短寿命票；ACL 删一行即可，这是表示税。",-1)),a[7]||(a[7]=A("p",null,[A("span",{class:"marginnote"},"数字实例：纪元（epoch）撤销像给票印批次号——系统当前纪元是 41，发出的票都盖 41；管理员把全局纪元拨到 42，所有 41 号票瞬间失效，不必逐张追回，代价是还没过期的好票也得重领。")],-1)),(e(),n(s,null,{default:E(()=>[r(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%EF%BC%9A%E4%BD%8E%E6%9D%83%E9%99%90%22%5D%20--%3E%7C%22%E9%80%92%E6%96%87%E4%BB%B6%E5%90%8D%E5%AD%97%E7%AC%A6%E4%B8%B2%22%7C%20S%5B%22%E9%AB%98%E6%9D%83%E9%99%90%E6%9C%8D%E5%8A%A1%22%5D%0A%20%20S%20--%3E%7C%22%E6%8C%89%E5%90%8D%E5%AD%97%E6%9F%A5%20ACL%20%E5%B9%B6%E6%89%93%E5%BC%80%22%7C%20F%5B%22%E6%95%8F%E6%84%9F%E6%96%87%E4%BB%B6%E8%A2%AB%E8%B6%8A%E6%9D%83%E6%89%93%E5%BC%80%22%5D%0A%20%20U2%5B%22%E5%90%8C%E4%B8%80%E7%94%A8%E6%88%B7%22%5D%20--%3E%7C%22%E9%80%92%E5%8F%AA%E8%AF%BB%E8%83%BD%E5%8A%9B%E7%A5%A8%22%7C%20S2%5B%22%E5%90%8C%E4%B8%80%E6%9C%8D%E5%8A%A1%22%5D%0A%20%20S2%20--%3E%7C%22%E5%8F%AA%E8%AE%A4%E7%A5%A8%EF%BC%8C%E7%A5%A8%E9%87%8C%E6%B2%A1%E6%9C%89%E9%82%A3%E4%B8%AA%E6%96%87%E4%BB%B6%22%7C%20OK%5B%22%E8%AE%BF%E9%97%AE%E8%A2%AB%E7%A5%A8%E7%9A%84%E8%8C%83%E5%9B%B4%E7%BA%A6%E6%9D%9F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把能力写成「更安全所以取代 ACL」。Web 资源、数据库 GRANT 仍大量是 ACL。也不要把区块链 token 插入本课。后课内存破坏会让两种表示都失效：若能改内核表或伪造票字节，表示层的论证作废。</p><p>能力传递要能衰减（只读、不可再传），否则最小特权在委托链上失控。后课默认：授权有 ACL 与能力两套语言；内存安全被破坏时，保护矩阵不再是有效边界。</p><p>两种表示可以在同一系统共存：查找用名字与 ACL，持有用 fd 与能力。设计要写清每一跳认的是哪一种。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>混淆代理人在「用高权限去解析用户给的名字」时出现；能力让后续只认票。</p></li><li><p>后课内存越界可以伪造票或改返回地址，表示层论证作废。</p></li><li><p>矩阵可按列（ACL）或按票（能力）实现。</p></li><li><p>能力利于委托与防混淆代理人；ACL 利于集中撤销。</p></li><li><p>内存越界一旦改控制流，两种票都可以作废——下一课只讲机制与防御直觉。</p></li><li><p>出处：Dennis and Van Horn, 1966；Lampson；Saltzer and Schroeder。</p></li></ul>',6))])}const b=o(C,[["render",d]]);export{h as __pageData,b as default};
